import { test, expect } from '@playwright/test';

test.describe('File Upload - Unsupported File Type Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display error message when uploading an unsupported file type', async ({ page }) => {
    // Intercept the file upload API call
    await page.route('**/api/upload', (route) => {
      route.abort('Failed to process file');
    });

    // Set up a mock response for the upload API
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Set up a mock response for the file validation API
    await page.route('**/api/validate-file', (route) => {
      route.abort('Unsupported file type');
    });

    // Set up a mock response for the file preview API
    await page.route('**/api/preview-file', (route) => {
      route.abort('Unsupported file type');
    });

    // Locate and interact with the file input using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('tests/fixtures/unsupported-file.txt');

    // Verify error message is displayed
    const errorMessage = page.getByText('Unsupported file type');
    await expect(errorMessage).toBeVisible();

    // Verify error icon is visible
    const errorIcon = page.getByTestId('error-icon');
    await expect(errorIcon).toBeVisible();

    // Verify file preview is not displayed
    const filePreview = page.getByTestId('file-preview');
    await expect(filePreview).not.toBeVisible();

    // Verify file upload button is disabled
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeDisabled();
  });

  test('should allow uploading supported file types and display preview', async ({ page }) => {
    // Intercept the file upload API call
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Set up a mock response for the file validation API
    await page.route('**/api/validate-file', (route) => {
      route.continue();
    });

    // Set up a mock response for the file preview API
    await page.route('**/api/preview-file', (route) => {
      route.continue();
    });

    // Locate and interact with the file input using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('tests/fixtures/supported-file.pdf');

    // Verify error message is not displayed
    const errorMessage = page.getByText('Unsupported file type');
    await expect(errorMessage).not.toBeVisible();

    // Verify file preview is displayed
    const filePreview = page.getByTestId('file-preview');
    await expect(filePreview).toBeVisible();

    // Verify file preview contains correct file name
    const previewText = page.getByText('Supported File.pdf');
    await expect(previewText).toBeVisible();

    // Verify file upload button is enabled
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeEnabled();

    // Verify file preview has correct file icon
    const fileIcon = page.getByTestId('file-icon');
    await expect(fileIcon).toBeVisible();
  });
});
